entries[172539] = { ["name"] = "Antiseptischer Verband", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\nRezept für 4 Einheiten. Die tatsächliche Anzahl hängt von Eurer Erste-Hilfe-Fertigkeit ab.\nBeruf:\nSchneiderei von Draenor (1)\n\nBenutzen: Heilt im Verlauf von 8 Sek. 2720 Schaden.\n35\n\"Die heilenden Eigenschaften des Seeskorpiongiftes können über die Haut aufgenommen werden, aber sie wirken nur langsam.\"" }
entries[172540] = { ["name"] = "Heiltonikum", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSeeskorpionsegment (10)\nErschafft 4 Stück Heiltonikum. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBeruf:\nAlchemie von Draenor (1)\n\nBenutzen: Stellt 3400 Gesundheit wieder her. (5 Min Abklingzeit)\n35\n\"Richtig vorbereitet kann das Gift des Seeskorpions Gesundheit wiederherstellen.\"" }
